head.script:
scwin.contnId;
scwin.fileRowcount;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        reId = $c.frame.path("../").fn_getId;
        scwin.contnId = reId();
        wrtr_id.hide();
        txb_page_gbn.hide();
        txb_wrt_dd.show("");
        file_name.hide();
        inf_find.hide();
        scwin.init(); // 시장구분

        // 수정화면 onload
        if (scwin.contnId !== "input") {
            await scwin.singleRead();
            if (rdo_kosdaq_bbs_tp_cd.getValue() === "10") {
                // 기업분석보고서
                txb_page_gbn.setValue("report2");
            } else if (rdo_kosdaq_bbs_tp_cd.getValue() === "12") {
                // 신규상장기업분석보고서
                txb_page_gbn.setValue("report5");
            } else if (rdo_kosdaq_bbs_tp_cd.getValue() === "23") {
                // 기업분석보고서(영문)
                txb_page_gbn.setValue("report2");
            } else if (rdo_kosdaq_bbs_tp_cd.getValue() === "13") {
                // 성장성보고서
                txb_page_gbn.setValue("report5");
            } else {
                txb_page_gbn.setValue("report2");
            }
            if (rdo_kosdaq_bbs_tp_cd.getValue() === "10" || rdo_kosdaq_bbs_tp_cd.getValue() === "23") {
                // 기업분석보고서, 기업분석보고서(영문), 성장성보고서
                label_3.hide();
                rdo_approv_yn.hide();
            } else {
                label_3.show("");
                rdo_approv_yn.show("");
            }
        } else {
            btn_delete.hide();
            label_3.hide();
            rdo_approv_yn.hide();

            // 등록화면 onload
            await scwin.setIrInfoHeader();
            // dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
            scwin.fileRowcount = 0;
            wrtr_id.setValue(js_id);
            txb_wrt_dd.setValue($c.ut.cGetToday("yyyymmdd"));
            if (rdo_kosdaq_bbs_tp_cd.getValue() === "10") {
                // 기업분석보고서
                txb_page_gbn.setValue("report2");
            } else if (rdo_kosdaq_bbs_tp_cd.getValue() === "12") {
                // 신규상장기업분석보고서
                txb_page_gbn.setValue("report5");
            } else if (rdo_kosdaq_bbs_tp_cd.getValue() === "23") {
                // 기업분석보고서(영문)
                txb_page_gbn.setValue("report2");
            } else if (rdo_kosdaq_bbs_tp_cd.getValue() === "13") {
                // 성장성보고서
                txb_page_gbn.setValue("report5");
            } else {
                txb_page_gbn.setValue("report2");
            }
            if (js_market === "1" || js_market === "2" || js_market === "6") {
                rdo_mkt_tp_cd.setValue(js_market); // 시장구분

            } else {
                rdo_mkt_tp_cd.setValue('1');
            }
            rdo_kosdaq_bbs_tp_cd.setValue('10'); // 보고서구분 : 디폴트 기업분석보고서

        }
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07245.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    rdo_mkt_tp_cd.setValue(js_market);
    if (js_market === "1" || js_market === "2" || js_market === "6") {
        rdo_mkt_tp_cd.setDisabled(true);
    } else {
        // 콘트롤 잠그기
        rdo_mkt_tp_cd.setDisabled(false);
        rdo_mkt_tp_cd.addClass("TopCondition_Blue");
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch_IR(txb_isur_cd, txb_com_abbrv);
        if (rdo_kosdaq_bbs_tp_cd.getValue() === "13") {
            if (scwin.contnId === 'input') {
                txb_title.setValue(txb_com_abbrv.getValue() + " 기업의 사업모델 평가보고서 및 기업 계속성 보고서");
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name trs_Read_OnSuccess
 * @description Read On Success 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Read_OnSuccess = function() {

};

/**
 * @method
 * @name trs_Read_OnFail
 * @description Read On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Read_OnFail = async function() {
    try {
        await $c.win.alert(trs_Read.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07245.trs_Read_OnFail" });
    }
};

/**
 * @method
 * @name trs_Update_OnSuccess
 * @description Update On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Update_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07245.trs_Update_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Update_OnFail
 * @description Update On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Update_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
        await $c.win.alert(trs_Update.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07245.trs_Update_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "등록"));
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07245.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "등록"));
        await $c.win.alert(trs_Save.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07245.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save_onclick = async function() {
    try {
        if (scwin.contnId !== "input") {
            await scwin.update();
        } else {
            await scwin.save();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07245.save_onclick" });
    }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delete_onclick = async function() {
    try {
        await scwin.delete();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07245.btn_delete_onclick" });
    }
};

/**
 * @method
 * @name trs_Delete_OnSuccess
 * @description Delete On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Delete_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07245.trs_Delete_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Delete_OnFail
 * @description Delete On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Delete_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
        await $c.win.alert(trs_Delete.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07245.trs_Delete_OnFail" });
    }
};

/**
 * @method
 * @name cancel_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cancel_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07245.cancel_onclick" });
    }
};

/**
 * @method
 * @name btn_lineadd_onclick
 * @description 「파일추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_lineadd_onclick = async function() {
    try {
        if (scwin.contnId !== "input") {
            scwin.fileRowcount = dts_fileList.getRowCount();
        }
        scwin.fileRowcount++;
        if (scwin.fileRowcount >= 4) {
            await $c.win.alert("더이상 추가하실수 없습니다.");
            scwin.fileRowcount = 4;
        } else {
            dts_fileList.insertRow();
            inf_find.open();
            if (inf_find.getValue() !== "") {
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
                file_name.setValue(inf_find.getValue());
            } else {
                dts_fileList.removeRow(dts_fileList.getRowPosition());
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07245.btn_lineadd_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 「파일삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function() {
    try {
        if (scwin.fileRowcount > 0) scwin.fileRowcount--;
        dts_fileList.removeRow(dts_fileList.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.btn_linedelete_onclick" });
    }
};

/**
 * @method
 * @name inf_find_OnClick
 * @description inf_find 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_OnClick = function() {
    try {
        const filenm = file_name.getValue();
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
        if (inf_find.getValue() === "") {
            file_name.setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.inf_find_OnClick" });
    }
};

/**
 * @method
 * @name grd_userlist_OnClick
 * @description grd_userlist 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_userlist_OnClick = function(row, colid) {
    try {
        if (row === 0) return;
        if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) === 0) {
            scwin.filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.grd_userlist_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
        if (rdo_kosdaq_bbs_tp_cd.getValue() === "13") {
            if (scwin.contnId === 'input') {
                txb_title.setValue(txb_com_abbrv.getValue() + " 기업의 사업모델 평가보고서 및 기업 계속성 보고서");
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name icn_SCal_onclick
 * @description icn_SCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_SCal_onclick = function() {
    try {
        popUpCalendar2(txb_noti_dd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.icn_SCal_onclick" });
    }
};

/**
 * @method
 * @name rdo_kosdaq_bbs_tp_cd_onclick
 * @description rdo_kosdaq_bbs_tp_cd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_kosdaq_bbs_tp_cd_onclick = function() {
    try {
        if (rdo_kosdaq_bbs_tp_cd.getValue() === "12" || rdo_kosdaq_bbs_tp_cd.getValue() === "13") {
            // 신규상장기업분석보고서,성장성보고서
            label_3.show("");
            rdo_approv_yn.show("");
            txb_page_gbn.setValue("report5");
            if (scwin.contnId === 'input') {
                if (rdo_kosdaq_bbs_tp_cd.getValue() === "13") {
                    txb_title.setValue(txb_com_abbrv.getValue() + " 기업의 사업모델 평가보고서 및 기업 계속성 보고서");
                }
            }
        } else {
            label_3.hide();
            rdo_approv_yn.hide();
            rdo_approv_yn.setValue("");
            txb_page_gbn.setValue("report2");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.rdo_kosdaq_bbs_tp_cd_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name singleRead
 * @description 기업분석보고서/신규상장기업분석보고서 개별조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.singleRead = async function() {
    // 기업분석보고서/신규상장기업분석보고서 개별조회
    trs_Read.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Read",
        action : "/IRMgt.do",
        ref : "dts_irCeoRoomSingle,dts_fileList",
        target : "trs_Read=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name update
 * @description 기업분석보고서/신규상장기업분석보고서 수정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    // 기업분석보고서/신규상장기업분석보고서 수정
    let pageGbn = txb_page_gbn.getValue();
    const kosdaqBbsTpCd = rdo_kosdaq_bbs_tp_cd.getValue();
    // alert(kosdaqBbsTpCd);

    if (txb_isur_cd.getValue() === "" || txb_isur_cd.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "회사(명)"));
        txb_isur_cd.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(txb_wrt_inst_nm, 80, "작성기관")) {
        txb_wrt_inst_nm.setValue("");
        txb_wrt_inst_nm.focus();
        return false;
    }
    if (txb_title.getValue() === "" || txb_title.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        txb_title.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(txb_title, 200, "제목")) {
        txb_title.setValue("");
        txb_title.focus();
        return false;
    }
    if (!await scwin.checkMaxLength2(maindoc_contn, 2000, "내용")) {
        maindoc_contn.text = "";
        maindoc_contn.focus();
        return false;
    }
    if (!$c.ut.isDate(txb_noti_dd.getValue())) {
        await $c.win.alert("[게시일자]를 확인하세요.");
        txb_noti_dd.focus();
        return false;
    }
    let rtn = confirm('내용을 수정 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        trs_Update.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Update",
            action : "/IRMgt.do",
            ref : "dts_irCeoRoomSingle,dts_fileList",
            target : "trs_Update=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

